package com.uade.tpo.foodmarketplace.controllers.ingrediente;
import java.net.URI; import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.uade.tpo.foodmarketplace.entity.ingrediente.Ingrediente; import com.uade.tpo.foodmarketplace.entity.dto.ingrediente.IngredienteRequest; import com.uade.tpo.foodmarketplace.entity.dto.common.ApiResponse; import com.uade.tpo.foodmarketplace.exceptions.ingrediente.IngredienteNotFoundException; import com.uade.tpo.foodmarketplace.service.ingrediente.IngredienteService; import jakarta.validation.Valid;
@RestController @RequestMapping("ingredientes") public class IngredientesController { private final IngredienteService service; public IngredientesController(IngredienteService service){this.service=service;}
@GetMapping public ResponseEntity<ApiResponse<List<Ingrediente>>> all(){List<Ingrediente>d=service.getIngredientes();return ResponseEntity.ok(ApiResponse.ok(d.isEmpty()?"No hay ingredientes disponibles":"Ingredientes obtenidos correctamente",d.isEmpty()?null:d));}
@GetMapping("/{id}") public ResponseEntity<ApiResponse<Ingrediente>> one(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok("Ingrediente obtenido correctamente",service.getIngredienteById(id).orElseThrow(IngredienteNotFoundException::new)));}
@PostMapping("createIngrediente") public ResponseEntity<ApiResponse<Ingrediente>> create(@Valid @RequestBody IngredienteRequest r){Ingrediente i=service.createIngrediente(r.getNombre(),r.getDescripcion());return ResponseEntity.created(URI.create("/ingredientes/"+i.getId())).body(ApiResponse.ok("Ingrediente creado correctamente",i));}
@PutMapping("/{id}") public ResponseEntity<ApiResponse<Ingrediente>> update(@PathVariable Long id,@Valid @RequestBody IngredienteRequest r){return ResponseEntity.ok(ApiResponse.ok("Ingrediente actualizado correctamente",service.updateIngrediente(id,r.getNombre(),r.getDescripcion())));}
@DeleteMapping("/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){service.deleteIngrediente(id);return ResponseEntity.ok(ApiResponse.ok("Ingrediente eliminado correctamente",null));}}
